/// static values defined in JavaScript's expressions
pub enum StaticValue {
    Boolean(HtmlSyntaxToken),
    Null(HtmlSyntaxToken),
    Undefined(HtmlSyntaxToken),
    Number(HtmlSyntaxToken),
    BigInt(HtmlSyntaxToken),
    // The string can be empty.
    String(HtmlSyntaxToken),
    /// This is used to represent the empty template string.
    EmptyString(TextRange),
}

